<template>
<div class="app" :style="appStyle">
  <div v-if="!userToken" class="login-wrap"><div class="login-card"><h1>🌳 匈牙利帖文一览 🌳</h1><input v-model="loginPassword" type="password" placeholder="普通用户密码" @keyup.enter="loginUser"/><button @click="loginUser">登录</button><div class="err">{{ error }}</div></div></div>
  <template v-else>
    <header class="topbar"><h1>🌳 匈牙利帖文一览 🌳</h1><div class="top-actions"><button @click="loadData">重新查询</button><button @click="showSettings=true">显示设置</button><button @click="showAdmin=true">管理中心</button><button @click="logout">退出</button></div></header>
