    </section>
    <section class="view-tabs"><button :class="{active:ui.view==='table'}" @click="ui.view='table';saveLocal()">表格视图</button><button :class="{active:ui.view==='landscape'}" @click="ui.view='landscape';saveLocal()">横版图片视图</button><button :class="{active:ui.view==='portrait'}" @click="ui.view='portrait';saveLocal()">竖版图片视图</button><span>共 {{total}} 条</span></section>
    <div v-if="loading" class="loading">加载中...</div>
    <div v-if="ui.view==='table'" class="table-wrap"><table :class="{noGrid:!ui.showGrid}"><thead><tr><th v-for="c in visibleColumns" :key="c.key" :style="headStyle(c)" :class="{sortable:isSortableColumn(c),sorted:filters.sort_by===sortKeyOf(c)}" @click="sortByColumn(c)"><span>{{c.label}}</span><span v-if="filters.sort_by===sortKeyOf(c)" class="sort-mark">{{filters.sort_dir==='asc'?'↑':'↓'}}</span></th><th :style="headStyle(actionCol)">操作</th></tr></thead><tbody><tr v-for="(r,idx) in rows" :key="r.post_id+'-'+idx" :style="rowStyle(idx)"><td v-for="c in visibleColumns" :key="c.key" :style="cellStyle(c)"><Cell :row="r" :col="c" :ui="ui" @detail="openDetail"/></td><td :style="cellStyle(actionCol)"><button @click="openDetail(r)">详情</button></td></tr></tbody></table></div>
    <div v-else class="cards" :class="ui.view"><div v-for="r in rows" :key="r.post_id" class="card"><div class="media" :style="{aspectRatio:currentCardConfig.ratio}"><img v-if="imageOf(r)" :src="imageOf(r)"/><div v-else class="noimg">无图</div></div><div class="card-body"><div v-if="currentCardConfig.avatar" class="page-title"><Avatar :src="r.page_avatar"/> <b>{{r.page_code}}</b></div><div class="id">{{r.post_id}}</div><div v-if="currentCardConfig.dates" class="meta">引流：{{formatDate(r.lead_date)}}　发帖：{{formatDate(r.post_time)}}</div><div v-if="currentCardConfig.gender" class="nums">男 {{formatGenderCell(r,'male')}} / 女 {{formatGenderCell(r,'female')}} / {{genderRatio(r)}}</div><div v-if="currentCardConfig.metrics" class="nums">引流 {{r.leads}} / 邀约 {{r.invites}} / 上线 {{r.online}} / 交教会 {{r.church}}</div><div v-if="currentCardConfig.engagement" class="nums">点赞 {{r.post_likes}} / 评论 {{r.post_comments}} / 分享 {{r.post_shares}}</div><div v-if="currentCardConfig.pageType" class="ptype">{{r.page_post_type}}</div><p v-if="currentCardConfig.summary">{{shortText(r.post_info)}}</p><div v-if="currentCardConfig.buttons" class="card-actions"><a :href="r.post_link" target="_blank">打开帖文</a><button @click="openDetail(r)">查看详情</button></div></div></div></div>
