    <div v-if="showSettings" class="modal-mask"><div class="modal settings-modal"><h2>显示设置</h2><div class="modal-actions"><button @click="exportStyle">导出当前样式配置</button><label class="import-btn">导入样式配置<input type="file" accept="application/json" @change="importStyle" hidden/></label><button @click="restoreAdminDefault">恢复管理员默认设置</button><button @click="resetLocal">清除本浏览器样式</button><button @click="showSettings=false">关闭</button></div><div class="settings-grid"><section><h3>基础样式</h3><label>字体大小<input type="number" v-model.number="ui.fontSize"/></label><label>行高<input type="number" v-model.number="ui.rowHeight"/></label><label>图片大小<input type="number" v-model.number="ui.imageSize"/></label><label>摘要字数<input type="number" v-model.number="ui.textLimit"/></label><label>详情宽度<input type="number" v-model.number="ui.drawerWidth"/></label><label><input type="checkbox" v-model="ui.showGrid"/>显示表格线</label><label>男女显示<select v-model="ui.genderMode"><option value="count_percent">数量+百分比</option><option value="count">只显示数量</option><option value="percent">只显示百分比</option></select></label><label>表头背景<input type="color" v-model="ui.headerBg"/></label><label>表头文字<input type="color" v-model="ui.headerColor"/></label><label>普通文字<input type="color" v-model="ui.textColor"/></label><label>表格线<input type="color" v-model="ui.gridColor"/></label><label>隔行底色<input type="color" v-model="ui.stripeBg"/></label><label>悬停底色<input type="color" v-model="ui.hoverBg"/></label></section><section><h3>图片视图</h3><div class="card-config"><h4>横版</h4><label v-for="f in cardFieldOptions" :key="'l'+f.key"><input type="checkbox" v-model="ui.landscape[f.key]"/>{{f.label}}</label><label>比例<input v-model="ui.landscape.ratio"/></label></div><div class="card-config"><h4>竖版</h4><label v-for="f in cardFieldOptions" :key="'p'+f.key"><input type="checkbox" v-model="ui.portrait[f.key]"/>{{f.label}}</label><label>比例<input v-model="ui.portrait.ratio"/></label></div></section></div><section><h3>表格列设置（可拖动，也可用按钮）</h3><div class="column-settings"><div v-for="(c,i) in sortedAllColumns" :key="c.key" class="column-row" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop="dropColumn(i)"><span class="drag">☰</span><input type="checkbox" v-model="c.visible"/><input class="label-input" v-model="c.label" placeholder="表头名"/><input type="number" v-model.number="c.width"/><select v-model="c.align"><option value="left">左</option><option value="center">中</option><option value="right">右</option></select><select v-model="c.displayMode"><option value="single">单行</option><option value="clip">截断</option><option value="wrap">换行</option><option value="lines">限制行数</option></select><input type="number" v-model.number="c.maxLines"/><label><input type="checkbox" v-model="c.detailOnly"/>只详情</label><button @click="moveColumn(i,-1)">上</button><button @click="moveColumn(i,1)">下</button><button @click="moveTop(i)">顶</button><button @click="moveBottom(i)">底</button></div></div></section><div class="modal-actions"><button @click="saveLocal();showSettings=false">保存到当前浏览器</button><button @click="showSettings=false">关闭</button></div></div></div>
    <div v-if="showAdmin" class="modal-mask"><div class="modal admin-modal"><h2>管理中心</h2><div v-if="!adminToken"><input v-model="adminPassword" type="password" placeholder="管理员密码" @keyup.enter="loginAdmin"/><button @click="loginAdmin">登录管理中心</button></div><div v-else class="admin-actions"><button @click="runSync">立即同步全部数据</button><button @click="saveAdminUi">保存当前样式为管理员默认</button><button @click="clearSyncCache">清空同步缓存</button><button @click="loadLogs">刷新同步日志</button><button @click="showAdmin=false">关闭</button><h3>同步日志</h3><table class="admin-table"><tr><th>ID</th><th>状态</th><th>信息</th><th>开始</th><th>结束</th></tr><tr v-for="l in logs" :key="l.id"><td>{{l.id}}</td><td>{{l.status}}</td><td>{{l.message}}</td><td>{{l.started_at}}</td><td>{{l.finished_at}}</td></tr></table></div><div class="err">{{adminError}}</div></div></div>
  </template>
</div>
</template>
<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref, watch } from 'vue'
const USER_KEY='POST_DASHBOARD_USER_TOKEN_V11', ADMIN_KEY='POST_DASHBOARD_ADMIN_TOKEN_V11', LOCAL_KEY='POST_DASHBOARD_LOCAL_STATE_V11'
const userToken=ref(localStorage.getItem(USER_KEY)||''), adminToken=ref(localStorage.getItem(ADMIN_KEY)||''), loginPassword=ref(''), adminPassword=ref(''), error=ref(''), adminError=ref('')
const admins=ref([]), pages=ref([]), rows=ref([]), total=ref(0), loading=ref(false), detail=ref(null), showSettings=ref(false), showAdmin=ref(false), logs=ref([]), activePage=ref('posts'), dragIndex=ref(null)
const functionPages=[{key:'posts',title:'帖文管理'},{key:'church',title:'交教会帖文'},{key:'leads',title:'引流排行榜'},{key:'invitesOverview',title:'邀约帖文总览'},{key:'onlineOverview',title:'上线帖文总览'}]
const baseColumns=[{key:'page_avatar',label:'头像',type:'avatar',width:58,align:'center',order:1,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'page_code',label:'专页',type:'text',width:96,align:'left',order:2,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'admin_name',label:'管理员',type:'text',width:80,align:'center',order:3,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'post_id',label:'ID',type:'text',width:120,align:'left',order:4,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'post_link',label:'链接',type:'link',width:62,align:'center',order:5,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'male',label:'男',type:'gender_male',width:88,align:'center',order:6,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'female',label:'女',type:'gender_female',width:88,align:'center',order:7,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'gender_ratio',label:'男女比',type:'gender_ratio',width:130,align:'center',order:8,visible:false,detailOnly:false,displayMode:'single',maxLines:1},{key:'leads',label:'引流',type:'number',width:58,align:'center',order:9,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'answers',label:'答题',type:'number',width:58,align:'center',order:10,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'invites',label:'邀约',type:'number',width:58,align:'center',order:11,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'online',label:'上线',type:'number',width:58,align:'center',order:12,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'church',label:'交教会',type:'number',width:72,align:'center',order:13,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'gained',label:'得人',type:'number',width:58,align:'center',order:14,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'display_media',label:'媒体',type:'image',width:90,align:'center',order:15,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'page_post_type',label:'类型',type:'text',width:140,align:'left',order:16,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'lead_date',label:'引流日',type:'date',width:105,align:'center',order:17,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'post_time',label:'发帖日',type:'date',width:110,align:'center',order:18,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'post_likes',label:'点赞',type:'number',width:82,align:'center',order:19,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'post_comments',label:'评论',type:'number',width:82,align:'center',order:20,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'post_shares',label:'分享',type:'number',width:82,align:'center',order:21,visible:true,detailOnly:false,displayMode:'single',maxLines:1},{key:'post_info',label:'内容',type:'text',width:260,align:'left',order:22,visible:true,detailOnly:false,displayMode:'lines',maxLines:2},{key:'post_info_translation',label:'内容译文',type:'text',width:260,align:'left',order:23,visible:false,detailOnly:false,displayMode:'lines',maxLines:2},{key:'post_ocr',label:'帖文OCR',type:'text',width:260,align:'left',order:24,visible:false,detailOnly:false,displayMode:'lines',maxLines:2},{key:'post_ocr_translation',label:'OCR译文',type:'text',width:260,align:'left',order:25,visible:false,detailOnly:false,displayMode:'lines',maxLines:2},{key:'video_original',label:'视频原文',type:'text',width:260,align:'left',order:26,visible:false,detailOnly:false,displayMode:'lines',maxLines:2},{key:'video_translation',label:'视频译文',type:'text',width:260,align:'left',order:27,visible:false,detailOnly:false,displayMode:'lines',maxLines:2},{key:'summary_source_name',label:'来源',type:'text',width:120,align:'left',order:28,visible:false,detailOnly:false,displayMode:'single',maxLines:1}]
const actionCol={key:'action',width:72,align:'center'}
const cardFieldOptions=[{key:'avatar',label:'专页头像'},{key:'dates',label:'日期'},{key:'gender',label:'男女比例'},{key:'metrics',label:'核心数据'},{key:'engagement',label:'互动数据'},{key:'pageType',label:'专页-帖文类型'},{key:'summary',label:'帖文摘要'},{key:'buttons',label:'按钮'}]
const ui=reactive({version:'v11',view:'table',fontSize:13,rowHeight:42,imageSize:72,textLimit:80,drawerWidth:560,showGrid:true,headerBg:'#f8fafc',headerColor:'#111827',textColor:'#111827',gridColor:'#e5e7eb',stripeBg:'#ffffff',hoverBg:'#eef6ff',globalMinLeads:2,adminMinLeads:{},genderMode:'count_percent',landscape:{ratio:'16/9',avatar:true,dates:true,gender:true,metrics:true,engagement:true,pageType:true,summary:true,buttons:true},portrait:{ratio:'9/16',avatar:true,dates:true,gender:true,metrics:true,engagement:false,pageType:true,summary:false,buttons:true},columns:[]})
const filters=reactive({admin:'__all__',date_type:'lead',start_date:todayStr(),end_date:todayStr(),page_code:'',sort_by:'',sort_dir:'desc',min_leads:2})
const Avatar=defineComponent({props:{src:String,label:String},setup(p){const broken=ref(false);watch(()=>p.src,()=>{broken.value=false});return()=>!p.src||broken.value?h('span',{class:'avatar avatar-empty'},avatarText(p.label)):h('img',{class:'avatar',src:p.src,onError:()=>{broken.value=true}})}})
const Cell=defineComponent({props:{row:Object,col:Object,ui:Object},emits:['detail'],setup(props){return()=>renderCell(props.row,props.col,props.ui)}})
function renderCell(row,col,ui){if(col.type==='avatar')return h(Avatar,{src:row.page_avatar,label:row.page_code||row.admin_name||''}); if(col.type==='image'){let src=imageOf(row); return src?h('img',{class:'thumb',style:{width:ui.imageSize+'px',height:ui.imageSize+'px'},src}):'-'} if(col.type==='link')return row[col.key]?h('a',{href:row[col.key],target:'_blank'},'打开'):''; return formatCell(row,col)}
const appStyle=computed(()=>({fontSize:ui.fontSize+'px',color:ui.textColor,'--grid-color':ui.gridColor,'--hover-bg':ui.hoverBg}))
const sortedAllColumns=computed(()=>ui.columns.sort((a,b)=>(a.order||0)-(b.order||0)))
const visibleColumns=computed(()=>sortedAllColumns.value.filter(c=>c.visible&&!c.detailOnly))
const currentCardConfig=computed(()=>ui.view==='portrait'?ui.portrait:ui.landscape)
const quickMode=ref('today')
function pad2(n){return String(n).padStart(2,'0')}
function makeYmd(y,m,d){return `${y}-${pad2(m)}-${pad2(d)}`}
function addMonthsYm(y,m,delta){let total=y*12+(m-1)+delta;return {y:Math.floor(total/12),m:total%12+1}}
function parisYmdParts(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return {y:Number(parts.find(p=>p.type==='year').value),m:Number(parts.find(p=>p.type==='month').value),d:Number(parts.find(p=>p.type==='day').value)}}
function todayStr(o=0){const d=new Date();d.setDate(d.getDate()-o);return makeYmd(d.getFullYear(),d.getMonth()+1,d.getDate())}
function monthStartStr(){const d=new Date();d.setDate(1);return makeYmd(d.getFullYear(),d.getMonth()+1,d.getDate())}
function ymd(d){return makeYmd(d.getFullYear(),d.getMonth()+1,d.getDate())}
function churchCycle(offset=0){const p=parisYmdParts();let sy,sm,ey,em;if(p.d>=23){sy=p.y;sm=p.m;const n=addMonthsYm(p.y,p.m,1);ey=n.y;em=n.m}else{const prev=addMonthsYm(p.y,p.m,-1);sy=prev.y;sm=prev.m;ey=p.y;em=p.m}if(offset){const s2=addMonthsYm(sy,sm,-offset);const e2=addMonthsYm(ey,em,-offset);sy=s2.y;sm=s2.m;ey=e2.y;em=e2.m}return {start:makeYmd(sy,sm,23),end:makeYmd(ey,em,22)}}
function setChurchCycle(offset=0,mode='church_current'){const c=churchCycle(offset);filters.start_date=c.start;filters.end_date=c.end;quickMode.value=mode;saveLocal();loadData()}
function headers(extra={}){return {'Content-Type':'application/json','X-User-Token':userToken.value,'X-Admin-Token':adminToken.value,...extra}}
async function api(url,opt={}){const res=await fetch(url,{...opt,headers:headers(opt.headers||{})}); if(!res.ok)throw new Error(await res.text()); return res.json()}
async function loginUser(){error.value='';try{const r=await fetch('/api/auth/user',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:loginPassword.value})}); if(!r.ok)throw new Error('密码错误'); const d=await r.json(); userToken.value=d.token; localStorage.setItem(USER_KEY,d.token); await init()}catch(e){error.value=e.message}}
function logout(){localStorage.removeItem(USER_KEY);localStorage.removeItem(ADMIN_KEY);userToken.value='';adminToken.value=''}
async function init(){await loadUi();restoreLocal();normalizeUi();await loadAdmins();await loadPages();await loadData()}
async function loadUi(){const remote=await api('/api/settings/ui');Object.assign(ui,remote);normalizeUi();setMinLeadsByAdmin()}
function normalizeUi(){if(!Array.isArray(ui.columns)||ui.columns.length===0)ui.columns=baseColumns.map(c=>({...c})); const known=new Set(ui.columns.map(c=>c.key)); baseColumns.forEach(c=>{if(!known.has(c.key))ui.columns.push({...c,order:ui.columns.length+1})}); ui.columns=ui.columns.map((c,i)=>({...baseColumns.find(b=>b.key===c.key),...c,order:c.order??i+1})); ['landscape','portrait'].forEach(k=>ui[k]={...(k==='landscape'?{ratio:'16/9'}:{ratio:'9/16'}),avatar:true,dates:true,gender:true,metrics:true,engagement:k==='landscape',pageType:true,summary:k==='landscape',buttons:true,...(ui[k]||{})})}
function setMinLeadsByAdmin(){filters.min_leads=filters.admin!=='__all__'?(ui.adminMinLeads?.[filters.admin]??ui.globalMinLeads):ui.globalMinLeads}
async function loadAdmins(){admins.value=await api('/api/admins')} async function loadPages(){pages.value=await api('/api/pages?admin='+encodeURIComponent(filters.admin))}
function setAdmin(a){filters.admin=a;filters.page_code='';setMinLeadsByAdmin();saveLocal();loadPages().then(loadData)}
function setPage(p){activePage.value=p;rows.value=[];total.value=0;if(detail)detail.value=null;filters.page_code='';if(p==='church'){filters.sort_by='church';setChurchCycle(0,'church_current');return}else{filters.start_date=todayStr();filters.end_date=todayStr();quickMode.value='today';if(p==='posts')filters.date_type='lead';if(p==='invitesOverview'||p==='onlineOverview')filters.date_type='invite';if(p==='leads')filters.sort_by='leads';if(p==='invitesOverview')filters.sort_by='invites';if(p==='onlineOverview')filters.sort_by='online'} saveLocal();loadData()}
function quickDay(o){filters.start_date=todayStr(o);filters.end_date=todayStr(o);quickMode.value=o===0?'today':o===1?'yesterday':'before';saveLocal();loadData()}
async function loadData(){loading.value=true;rows.value=[];total.value=0;try{const p=new URLSearchParams();p.set('admin',filters.admin); if(filters.page_code)p.set('page_code',filters.page_code); if(filters.start_date)p.set('start_date',filters.start_date); if(filters.end_date)p.set('end_date',filters.end_date); if(activePage.value==='posts'||activePage.value==='leads'){p.set('min_leads',String(Number(filters.min_leads)||0))}else{p.set('min_leads','0')} p.set('limit','1000'); let url='/api/posts?'; if(activePage.value==='church'){p.set('project','church');p.set('mode','all');p.set('sort_by',filters.sort_by||'church');p.set('sort_dir',filters.sort_dir||'desc');url='/api/project-posts?'} else if(activePage.value==='leads'){p.set('metric','leads');if(filters.sort_by)p.set('sort_by',filters.sort_by);p.set('sort_dir',filters.sort_dir||'desc');url='/api/ranking?'} else if(activePage.value==='invitesOverview'||activePage.value==='onlineOverview'){p.set('metric',activePage.value==='invitesOverview'?'invites':'online');p.set('date_type',filters.date_type||'invite');if(filters.sort_by)p.set('sort_by',filters.sort_by);p.set('sort_dir',filters.sort_dir||'desc');url='/api/overview?'} else {p.set('date_type',filters.date_type); if(filters.sort_by)p.set('sort_by',filters.sort_by); p.set('sort_dir',filters.sort_dir||'desc');url='/api/posts?'} const d=await api(url+p.toString());rows.value=Array.isArray(d.rows)?d.rows:[];total.value=Number(d.total||0);saveLocal()}catch(e){console.error('loadData failed',e);rows.value=[];total.value=0;error.value='数据加载失败：'+(e.message||e)}finally{loading.value=false}}
function saveLocal(){normalizeUi();localStorage.setItem(LOCAL_KEY,JSON.stringify({ui:JSON.parse(JSON.stringify(ui)),filters:JSON.parse(JSON.stringify(filters)),activePage:activePage.value}))}
let saveTimer=null
function saveLocalDebounced(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveLocal(),500)}
watch(ui,saveLocalDebounced,{deep:true})
watch(filters,saveLocalDebounced,{deep:true})
watch(activePage,saveLocalDebounced)
watch(quickMode,saveLocalDebounced)
function restoreLocal(){const raw=localStorage.getItem(LOCAL_KEY);if(!raw)return;try{const d=JSON.parse(raw);if(d.ui)Object.assign(ui,d.ui);if(d.filters)Object.assign(filters,d.filters);if(d.activePage)activePage.value=d.activePage}catch{}}
function resetLocal(){localStorage.removeItem(LOCAL_KEY);location.reload()}
async function restoreAdminDefault(){localStorage.removeItem(LOCAL_KEY);await loadUi();normalizeUi();saveLocal();await loadData();alert('已恢复管理员默认设置')}
function formatDate(v){return v?String(v).replace('T',' ').slice(0,10):''}
function pct(n,d){return d?Math.round(n*100/d)+'%':'0%'}
function formatGenderCell(row,key){const m=Number(row.male)||0,f=Number(row.female)||0,t=m+f,n=key==='male'?m:f;if(ui.genderMode==='count')return String(n);if(ui.genderMode==='percent')return pct(n,t);return `${n} / ${pct(n,t)}`}
function genderRatio(row){const m=Number(row.male)||0,f=Number(row.female)||0,t=m+f;return `男 ${pct(m,t)} / 女 ${pct(f,t)}`}
function formatCell(row,col){if(col.type==='gender_male')return formatGenderCell(row,'male');if(col.type==='gender_female')return formatGenderCell(row,'female');if(col.type==='gender_ratio')return genderRatio(row);if(col.type==='date')return formatDate(row[col.key]);return row[col.key]??''}
const SORTABLE_COLUMNS={leads:'leads',invites:'invites',online:'online',church:'church',gained:'gained',post_likes:'post_likes',post_comments:'post_comments',post_shares:'post_shares'}
function sortKeyOf(c){return SORTABLE_COLUMNS[c.key]||''}
function isSortableColumn(c){return !!sortKeyOf(c)}
function sortByColumn(c){const k=sortKeyOf(c);if(!k)return;if(filters.sort_by===k){filters.sort_dir=filters.sort_dir==='asc'?'desc':'asc'}else{filters.sort_by=k;filters.sort_dir='desc'}saveLocal();loadData()}
function avatarText(v){const s=(v||'').toString().trim();return s?s.slice(0,1).toUpperCase():'—'}

function shortText(v){const s=v==null?'':String(v);return s.length>ui.textLimit?s.slice(0,ui.textLimit)+'...':s}
function imageOf(r){return r.display_media||r.image_link||''}
function openDetail(r){detail.value=r}
function headStyle(c){return {width:(c.width||100)+'px',minWidth:(c.width||100)+'px',background:ui.headerBg,color:ui.headerColor,borderColor:ui.gridColor,textAlign:c.align||'center'}}
function cellStyle(c){return {width:(c.width||100)+'px',minWidth:(c.width||100)+'px',maxWidth:(c.width||100)+'px',borderColor:ui.gridColor,textAlign:c.align||'left'}}
function rowStyle(i){return {height:ui.rowHeight+'px',background:i%2?ui.stripeBg:'#fff'}}
function reorder(arr){arr.forEach((c,i)=>c.order=i+1)}
function moveColumn(i,delta){const arr=sortedAllColumns.value;const j=i+delta;if(j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];reorder(arr);ui.columns=[...arr];saveLocal()}
function moveTop(i){const arr=sortedAllColumns.value;arr.unshift(arr.splice(i,1)[0]);reorder(arr);ui.columns=[...arr];saveLocal()}
function moveBottom(i){const arr=sortedAllColumns.value;arr.push(arr.splice(i,1)[0]);reorder(arr);ui.columns=[...arr];saveLocal()}
function dropColumn(i){const arr=sortedAllColumns.value;const from=dragIndex.value;if(from===null||from===i)return;const item=arr.splice(from,1)[0];arr.splice(i,0,item);reorder(arr);ui.columns=[...arr];dragIndex.value=null;saveLocal()}
function exportStyle(){saveLocal();const data={version:'v11',exportedAt:new Date().toISOString(),ui:JSON.parse(JSON.stringify(ui)),filters:JSON.parse(JSON.stringify(filters)),activePage:activePage.value};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='post-dashboard-style-v8-'+new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')+'.json';a.click();URL.revokeObjectURL(a.href)}
async function importStyle(e){const f=e.target.files?.[0];if(!f)return;const txt=await f.text();const data=JSON.parse(txt);let cfg=data;if(data.localStorage){const key=Object.keys(data.localStorage).find(k=>/POST_DASHBOARD.*STATE/i.test(k));cfg=key?JSON.parse(data.localStorage[key]):data} if(cfg.ui)Object.assign(ui,cfg.ui); if(cfg.filters)Object.assign(filters,cfg.filters); if(cfg.activePage)activePage.value=cfg.activePage; normalizeUi();saveLocal();alert('已导入到当前浏览器')}
async function loginAdmin(){adminError.value='';try{const r=await fetch('/api/auth/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:adminPassword.value})});if(!r.ok)throw new Error('管理员密码错误');const d=await r.json();adminToken.value=d.token;localStorage.setItem(ADMIN_KEY,d.token);await loadLogs()}catch(e){adminError.value=e.message}}
async function runSync(){adminError.value='正在同步，请等待...';try{const d=await api('/api/sync/run',{method:'POST'});adminError.value=d.message||'同步完成';await loadAdmins();await loadPages();await loadData();await loadLogs()}catch(e){adminError.value=e.message}}
async function loadLogs(){logs.value=await api('/api/sync/logs')}
async function saveAdminUi(){normalizeUi();await fetch('/api/settings/ui',{method:'PUT',headers:headers(),body:JSON.stringify({value:ui})});adminError.value='已保存为管理员全局默认'}
async function clearSyncCache(){if(!confirm('确认清空同步缓存？会清空排行、项目、未匹配数据。'))return;await api('/api/settings/clear-sync-cache',{method:'POST'});adminError.value='已清空同步缓存'}
onMounted(async()=>{if(userToken.value){try{await init()}catch(e){localStorage.removeItem(USER_KEY);userToken.value=''}}})
</script>
<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,"Microsoft YaHei",sans-serif;background:#f3f4f6;color:#111827}.app,.app *{font-size:inherit}button,.import-btn{cursor:pointer;border:1px solid #cbd5e1;background:white;border-radius:8px;padding:7px 11px;display:inline-flex;align-items:center}button:hover,button.active,.import-btn:hover{background:#16a34a;color:white;border-color:#16a34a}input,select{padding:7px;border:1px solid #cbd5e1;border-radius:8px}.login-wrap{min-height:100vh;display:flex;align-items:center;justify-content:center}.login-card{background:white;padding:30px;width:360px;border-radius:16px;box-shadow:0 10px 30px #0001;display:grid;gap:14px}.login-card h1,.topbar h1{font-size:20px;margin:0}.err{color:#dc2626}.topbar{display:flex;justify-content:space-between;align-items:center;padding:12px 18px;background:white;border-bottom:1px solid #e5e7eb}.top-actions,.admin-tabs,.page-tabs,.view-tabs,.modal-actions{display:flex;gap:8px;flex-wrap:wrap}.admin-tabs{padding:10px 16px 5px;background:#fff;border-bottom:1px dashed #e5e7eb}.page-tabs{padding:7px 16px 10px;background:#fff;border-bottom:1px solid #e5e7eb}.filters{margin:14px 16px;background:white;padding:14px;border-radius:14px;display:flex;gap:12px;flex-wrap:wrap;align-items:end}.filters label{display:grid;gap:4px;color:#475569}.view-tabs{margin:14px 16px;align-items:center}.loading{margin:16px}.table-wrap{margin:16px;background:white;border-radius:14px;overflow:auto;max-height:calc(100vh - 245px)}table{border-collapse:collapse;width:max-content;min-width:100%}th,td{padding:7px 8px;vertical-align:middle;white-space:nowrap;border:1px solid var(--grid-color);overflow:hidden;text-overflow:ellipsis}table.noGrid th,table.noGrid td{border-color:transparent!important}thead th{position:sticky;top:0;z-index:2;font-weight:700}tbody tr:hover{background:var(--hover-bg)!important}.thumb{object-fit:cover;border-radius:8px;background:#f1f5f9}.avatar{width:32px;height:32px;border-radius:50%;object-fit:cover;vertical-align:middle;background:#e5e7eb;display:inline-flex;align-items:center;justify-content:center}.avatar-empty{color:#94a3b8}.cards{margin:16px;display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:16px}.cards.portrait{grid-template-columns:repeat(auto-fill,minmax(260px,1fr))}.card{background:white;border-radius:14px;overflow:hidden;box-shadow:0 4px 14px #0000000d}.media{background:#e2e8f0;display:flex;align-items:center;justify-content:center}.media img{width:100%;height:100%;object-fit:cover}.noimg{color:#64748b}.card-body{padding:12px;display:grid;gap:6px}.id{font-weight:bold}.meta,.nums,.ptype{color:#475569}.page-title{display:flex;align-items:center;gap:8px}.card-actions{display:flex;gap:8px;align-items:center}.drawer{position:fixed;top:0;right:0;height:100vh;background:white;box-shadow:-10px 0 30px #0002;padding:18px;overflow:auto;z-index:10}.close{float:right;font-size:24px}.bigimg{width:100%;border-radius:12px;margin-bottom:12px}.detail-grid{display:grid;grid-template-columns:110px 1fr;gap:8px;margin:12px 0}pre{white-space:pre-wrap;background:#f8fafc;padding:10px;border-radius:8px}.modal-mask{position:fixed;inset:0;background:#0006;display:flex;align-items:center;justify-content:center;z-index:20}.modal{background:white;width:700px;max-height:88vh;overflow:auto;border-radius:16px;padding:20px;display:grid;gap:12px}.settings-modal{width:1100px}.admin-modal{width:900px}.modal h2{font-size:20px;margin:0 0 8px}.modal h3{font-size:15px;margin:6px 0}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.modal section{border:1px solid #e5e7eb;border-radius:12px;padding:12px;display:grid;gap:10px}.modal label{display:flex;justify-content:space-between;align-items:center;gap:12px}.column-settings{display:grid;gap:6px;max-height:420px;overflow:auto}.column-row{display:grid;grid-template-columns:30px 45px 160px 90px 80px 95px 80px 80px repeat(4,45px);gap:8px;align-items:center;padding:6px;border-bottom:1px solid #f1f5f9}.drag{cursor:move;color:#64748b}.admin-table{width:100%;font-size:12px}.admin-table td,.admin-table th{white-space:normal;border:1px solid #e5e7eb}a{color:#2563eb}.sortable{cursor:pointer;user-select:none}.sortable:hover{filter:brightness(.96)}.sort-mark{margin-left:5px;font-weight:700;color:#16a34a}.sorted{box-shadow:inset 0 -2px 0 #16a34a}.label-input{width:100%;min-width:0}.avatar-empty{font-weight:700;color:#64748b;background:#e2e8f0}
</style>
